(434,'Un baile inesperado','describir una experiencia y matizar una reacción','La novia siria','2004','O filme de Eran Riklis aborda fronteiras, família e escolhas. A cena autoral acompanha dois amigos que lembram um baile inesperado e discutem como reagiram.', [('baile','dança','BÁI-le'),('sorpresa','surpresa','sor-PRÊ-sa'),('pareja','casal','pa-RÊ-ra'),('música','música','MÚ-si-ka'),('reacción','reação','re-ak-SIÓN'),('recuerdo','lembrança','re-KUÊR-do')], ['bailar','reaccionar','reconocer','comentar'], [('A decir verdad','Para dizer a verdade'),('Sin embargo','No entanto'),('Por lo visto','Pelo visto'),('Al fin y al cabo','No fim das contas')], ('b e v',['baile','pareja','música']), ['Nora','César'], [('Nunca habían bailado tan cerca.','Nunca tinham dançado tão perto.'),('La música empezó sin aviso.','A música começou sem aviso.'),('Por lo visto, la pareja conocía la canción.','Pelo visto, o casal conhecia a canção.'),('A decir verdad, me sorprendió su reacción.','Para dizer a verdade, a reação deles me surpreendeu.'),('Sin embargo, todos seguimos el ritmo.','No entanto, todos seguimos o ritmo.'),('¿Reconociste al cantante?','Você reconheceu o cantor?'),('Sí, y comenté el recuerdo después.','Sim, e comentei a lembrança depois.'),('Al fin y al cabo, fue una noche alegre.','No fim das contas, foi uma noite alegre.')], [('**A decir verdad**, no esperaba bailar.','Para dizer a verdade, não esperava dançar.'),('**Sin embargo**, la música nos acercó.','No entanto, a música nos aproximou.'),('**Por lo visto**, alguien cambió la lista.','Pelo visto, alguém mudou a lista.'),('**Al fin y al cabo**, todos disfrutamos.','No fim das contas, todos aproveitamos.'),('Después hablamos de la sorpresa.','Depois falamos da surpresa.'),('La reacción fue más tranquila de lo esperado.','A reação foi mais tranquila do que o esperado.'),('Cada recuerdo guarda un ritmo.','Cada lembrança guarda um ritmo.'),('Y la noche terminó con una sonrisa.','E a noite terminou com um sorriso.')]),
