(437,'Historias de frontera','narrar encontros e comparar perspectivas','El árbol de la memoria','2010','A obra aborda memória e pertencimento em uma comunidade imaginada. A cena autoral reúne viajantes que atravessaram uma fronteira e comparam suas perspectivas.', [('frontera','fronteira','fron-TÊ-ra'),('pasaporte','passaporte','pa-sa-PÔR-te'),('aduana','alfândega','a-du-Á-na'),('testimonio','testemunho','tes-ti-MÔ-nio'),('perspectiva','perspectiva','pers-pek-TÍ-ba'),('encuentro','encontro','en-KUÊN-tro')], ['cruzar','mostrar','escuchar','comparar'], [('Desde mi punto de vista','Do meu ponto de vista'),('En cambio','Em contrapartida'),('Por lo que sé','Pelo que sei'),('En resumidas cuentas','Em resumo')], ('j e rr',['frontera','pasaporte','encuentro']), ['Amina','Jorge'], [('Las historias de frontera cambian según quién las cuenta.','As histórias de fronteira mudam conforme quem as conta.'),('Amina mostró su pasaporte en la aduana.','Amina mostrou seu passaporte na alfândega.'),('Jorge cruzó por otra carretera.','Jorge atravessou por outra estrada.'),('Por lo que sé, ambos llegaron el mismo día.','Pelo que sei, ambos chegaram no mesmo dia.'),('Desde mi punto de vista, cada testimonio importa.','Do meu ponto de vista, cada testemunho importa.'),('En cambio, la perspectiva de Jorge es distinta.','Em contrapartida, a perspectiva de Jorge é diferente.'),('¿Escuchamos los dos relatos?','Ouvimos os dois relatos?'),('En resumidas cuentas, el encuentro nos acercó.','Em resumo, o encontro nos aproximou.')], [('**Desde mi punto de vista**, la frontera también es memoria.','Do meu ponto de vista, a fronteira também é memória.'),('**En cambio**, otro testimonio destaca el viaje.','Em contrapartida, outro testemunho destaca a viagem.'),('**Por lo que sé**, faltan documentos del archivo.','Pelo que sei, faltam documentos do arquivo.'),('**En resumidas cuentas**, escuchamos antes de juzgar.','Em resumo, ouvimos antes de julgar.'),('Después comparamos las rutas.','Depois comparamos as rotas.'),('Cada testimonio merece contexto.','Cada testemunho merece contexto.'),('El encuentro no borra las diferencias.','O encontro não apaga as diferenças.'),('Y la frontera adquiere otra lectura.','E a fronteira adquire outra leitura.')]),
